export const getGetSnippetQueryKey = (id: number,) => {
    return [
    `/api/snippets/${id}`
    ] as const;
    }


export const getGetSnippetQueryOptions = <TData = Awaited<ReturnType<typeof getSnippet>>, TError = ErrorType<void>>(id: number, options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof getSnippet>>, TError, TData>, request?: SecondParameter<typeof customFetch>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getGetSnippetQueryKey(id);



    const queryFn: QueryFunction<Awaited<ReturnType<typeof getSnippet>>> = ({ signal }) => getSnippet(id, { signal, ...requestOptions });





   return  { queryKey, queryFn, enabled: id !== null && id !== undefined, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof getSnippet>>, TError, TData> & { queryKey: QueryKey }
}

